// flatten returns the Terraform model of the resource in an API response.
// A value that the response does not have is null.
func flatten(ctx context.Context, v *alert_definitions_service.AlertDef) (*AlertDefModel, diag.Diagnostics) {
	var diags diag.Diagnostics
	if v == nil {
		diags.AddError("Missing resource", "The API response has no AlertDef.")
		return nil, diags
	}
	if v.AlertDefProperties == nil {
		// The top-level attributes are fields of this object, so a response without it has no resource.
		diags.AddError("Missing resource", "The API response has no alertDefProperties.")
		return nil, diags
	}
	out := flattenAlertDef(ctx, path.Empty(), v, &diags)
	if out.Id.IsNull() || out.Id.ValueString() == "" {
		diags.AddError("Missing id", "The API response has no id. Without it, Terraform cannot read, update, or delete the resource.")
	}
	return out, diags
}

